<?php
namespace App\Http\Controllers;
use App\Models\{SalesInvoice,PurchaseInvoice,Budget,Expense}; use App\Services\BudgetTracker; use Carbon\Carbon; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\StreamedResponse;
class ReportController extends Controller {
 public function index(Request $request,BudgetTracker $tracker){[$from,$to]=$this->range($request);$sales=SalesInvoice::with('customer')->whereBetween('issue_date',[$from,$to])->get();$purchases=PurchaseInvoice::whereBetween('issue_date',[$from,$to])->get();$expenses=Expense::whereBetween('expense_date',[$from,$to])->get();$budgets=Budget::with('expenses')->where('period_start','<=',$to)->where('period_end','>=',$from)->get();$months=[];$cursor=$from->copy()->startOfMonth();while($cursor->lte($to)){$months[]=$cursor->format('Y-m');$cursor->addMonth();}$monthly=fn($rows)=>collect($months)->map(fn($month)=>$rows->filter(fn($row)=>Carbon::parse($row->issue_date)->format('Y-m')===$month)->sum(fn($row)=>(float)$row->total));$status=collect(['Paid','Pending','Overdue'])->mapWithKeys(fn($name)=>[$name=>['count'=>$sales->where('status',$name)->count(),'amount'=>$sales->where('status',$name)->sum(fn($i)=>(float)$i->total)]]);$budgetRows=$budgets->map(fn($b)=>['name'=>$b->name,'budget'=>(string)$b->amount,'actual'=>$tracker->summarize($b)['used']]);$customers=$sales->groupBy('customer_id')->map(fn($g)=>['name'=>$g->first()->customer->name,'total'=>$g->sum(fn($i)=>(float)$i->total)])->sortByDesc('total')->take(5)->values();$categories=$expenses->groupBy('category')->map(fn($g)=>$g->sum(fn($e)=>(float)$e->amount))->sortDesc();$monthlySales=$monthly($sales)->values();$monthlyPurchases=$monthly($purchases)->values();return view('reports.index',compact('from','to','months','monthlySales','monthlyPurchases','status','budgetRows','customers','categories'));}
 public function csv(Request $request,string $report,BudgetTracker $tracker):StreamedResponse {[$from,$to]=$this->range($request);$rows=[];$headers=[];if($report==='sales-purchases'){$headers=['Month','Sales','Purchases'];$sales=SalesInvoice::whereBetween('issue_date',[$from,$to])->get();$purchases=PurchaseInvoice::whereBetween('issue_date',[$from,$to])->get();for($date=$from->copy()->startOfMonth();$date->lte($to);$date->addMonth()){$month=$date->format('Y-m');$rows[]=[$month,$sales->filter(fn($i)=>Carbon::parse($i->issue_date)->format('Y-m')===$month)->sum('total'),$purchases->filter(fn($i)=>Carbon::parse($i->issue_date)->format('Y-m')===$month)->sum('total')];}}elseif($report==='statuses'){$headers=['Status','Count','Amount'];$invoices=SalesInvoice::whereBetween('issue_date',[$from,$to])->get();foreach(['Paid','Pending','Overdue'] as $status)$rows[]=[$status,$invoices->where('status',$status)->count(),$invoices->where('status',$status)->sum('total')];}elseif($report==='budgets'){$headers=['Budget','Budget amount','Actual'];$budgets=Budget::with('expenses')->where('period_start','<=',$to)->where('period_end','>=',$from)->get();foreach($budgets as $budget){$summary=$tracker->summarize($budget);$rows[]=[$budget->name,$budget->amount,$summary['used']];}}elseif($report==='customers'){$headers=['Customer','Sales total'];$sales=SalesInvoice::with('customer')->whereBetween('issue_date',[$from,$to])->get();$sales->groupBy('customer_id')->map(fn($g)=>[$g->first()->customer->name,$g->sum('total')])->sortByDesc(fn($row)=>$row[1])->take(5)->each(fn($row)=>$rows[]=$row);}elseif($report==='expenses'){$headers=['Category','Amount'];$expenses=Expense::whereBetween('expense_date',[$from,$to])->get()->groupBy('category');foreach($expenses as $category=>$group)$rows[]=[$category,$group->sum('amount')];}else{abort(404);}return response()->streamDownload(function()use($headers,$rows){$handle=fopen('php://output','w');fputcsv($handle,$headers);foreach($rows as $row)fputcsv($handle,$row);fclose($handle);},$report.'.csv',['Content-Type'=>'text/csv']);}
 private function range(Request $request):array{$defaultFrom=now()->month>=4?now()->startOfYear()->addMonths(3):now()->startOfYear()->subMonths(9);$from=Carbon::parse($request->input('from',$defaultFrom->toDateString()))->startOfDay();$to=Carbon::parse($request->input('to',now()->toDateString()))->endOfDay();if($from->gt($to))abort(redirect()->route('reports.index')->withErrors(['from'=>'The from date must not be after the to date.']));return[$from,$to];}
}
